    n = int(lines[0])

    # Read spaceship coordinates
    spaceships = []
    for i in range(n):
        x, y = map(int, lines[2 * i + 2].split())
        spaceships.append({'id': i + 1, 'x': x, 'y': y, 'is_ship': True})

    # Read base coordinates
    bases = []
    for i in range(n):
        x, y = map(int, lines[2 * n + 1 + i].split())
        bases.append({'id': i + 1, 'x': x, 'y': y, 'is_ship': False})

    # Combine all points
    all_points = spaceships + bases

    # Calculate centroid
    cx = sum(p['x'] for p in all_points) / n
    cy = sum(p['y'] for p in all_points) / n

    # Sort by angle around centroid
    def angle(p):
        return math.atan2(p['y'] - cy, p['x'] - cx)

    all_points.sort(key=angle)

    # Match spaceships and bases alternately
    spaceship_results = {}
    ship_idx = 0

    # We'll iterate through sorted points and match
    result = [0] * n

    # Greedy approach: match spaceship i to base at same index
    ship_indices = sorted(range(n), key=lambda i: angle(spaceships[i]))

    base_indices = sorted(range(n), key=lambda i: angle(bases[i]))

    # Map spaceship original index to base original index
    for s_idx in ship_indices:
        # Find which base we're matching - use sorted order
        b_idx = base_indices[s_idx]
        result[s_idx - 1] = base_indices[s_idx]

    # Convert to string
    output = '\n'.join(str(result[i]) for i in range(n))
    return output

