def get_divisors(n):
    d = []
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            d.append(i)
            if i != n // i:
                d.append(n // i)
    if n > 1 and n not in d:
        d.append(n)
    return sorted(d)

def get_prime_factors(x):
    factors = set()
    d = 2
    temp = x
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def get_shared_primes(a, b):
    return get_prime_factors(a) & get_prime_factors(b)

def can_arrange(divisors):
    if len(divisors) <= 2:
        return True

    # Compute prime factors for each divisor
    num_divisors = len(divisors)
    primes = [get_prime_factors(d) for d in divisors]

    # Build adjacency based on shared primes
    adj = [set() for _ in range(num_divisors)]
    for i in range(num_divisors):
        for j in range(i + 1, num_divisors):
            if primes[i] & primes[j]:  # Share at least one prime
                adj[i].add(j)
                adj[j].add(i)

    # Check if graph is connected and can form a cycle with all edges satisfying gcd>1
    visited = [False] * num_divisors
    nodes = []
    stack = [0]
    visited[0] = True

    while stack:
        u = stack.pop()
        nodes.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                stack.append(v)

    if len(nodes) != num_divisors:
        return False

    # Try to find a Hamiltonian cycle using backtracking (for small number of divisors)
    order = []
    used = [False] * num_divisors

    def backtrack(last, count):
        if count == num_divisors:
            # Check if last connects to first
            if 0 in adj[last]:
                return True
            return False

        for v in adj[last]:
            if not used[v]:
                used[v] = True
                order.append(v)
                if backtrack(v, count + 1):
                    return True
                order.pop()
                used[v] = False

        return False

    used[0] = True
    order.append(0)

    if backtrack(0, 1):
        return True

    # For larger cases, use a simpler heuristic: greedy cycle construction
    order = [0]
    used = [True] + [False] * (num_divisors - 1)

    for _ in range(num_divisors - 1):
        last = order[-1]
        found = False
        for v in adj[last]:
            if not used[v]:
                order.append(v)
                used[v] = True
                found = True
                break
        if not found:
            return False

    # Check if last connects to first
    if 0 in adj[order[-1]]:
        return True

    return False

