def is_bitonic(arr):
    """Check if an array is bitonic (increases then decreases)."""
    n = len(arr)
    if n <= 2:
        return True

    # Find the maximum
    max_idx = arr.index(max(arr))

    # Check it's the only maximum
    for i in range(n):
        if arr[i] == max(arr) and i != max_idx:
            return False

    # Check increasing before max
    for i in range(max_idx):
        if arr[i] >= arr[i+1]:
            return False

    # Check decreasing after max
    for i in range(max_idx, n-1):
        if arr[i] <= arr[i+1]:
            return False

    return True

