def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO\n"

    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])

    clauses = []
    ptr = 1
    for _ in range(n):
        parts = list(map(int, lines[ptr].split()))
        k = parts[0]
        literals = parts[1:]
        clauses.append((k, literals))
        ptr += 1

    # Nodes: 1..m for positive literals, m+1..2m for negative literals
    parent = list(range(2 * m + 2))

    def find(x):
        if parent[x] == x:
            return x
        parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        x_root, y_root = find(x), find(y)
        if x_root != y_root:
            parent[x_root] = y_root
            return True
        return False

    def lit_to_node(lit):
        """Map literal to node: positive lit -> lit, negative lit -> m + abs(lit)"""
        if lit > 0:
            return lit
        return m + abs(lit)

    # Build implication graph
    for k, literals in clauses:
        for i in range(k):
            # For clause (l1 OR l2 OR ...), we add ¬li → lj for all j
            neg_lit = -literals[i]
            neg_node = lit_to_node(neg_lit)
            for j in range(k):
                if i == j:
                    continue
                lj = literals[j]
                union(neg_node, lit_to_node(lj))

    # Check for contradictions: if x and ¬x are in same component
    for i in range(1, m + 1):
        if find(i) == find(m + i):
            return "NO\n"

    # Generate assignment: x_i is true if find(i) != find(m+i)
    assignment = [0] * (m + 1)
    for i in range(1, m + 1):
        if find(i) != find(m + i):
            assignment[i] = 1
        else:
            # Default to true if literal node exists
            assignment[i] = 1

    result = []
    for i in range(1, m + 1):
        result.append(str(assignment[i]))

    return "YES\n" + "".join(result)

