    lines = input_text.strip().split('\n')
    if not lines:
        return '0\n'

    first_line = lines[0].split()
    N, M, K = int(first_line[0]), int(first_line[1]), int(first_line[2])

    transformers = []
    for i in range(1, K + 1):
        if i < len(lines):
            parts = lines[i].split()
            if len(parts) >= 5:
                x, y, d, t, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
                transformers.append((x, y, d, t, e))

    # dp[r][c] = min energy to reach cell (r,c)
    # Since we start at (0,0) at time 0 and reach (r,c) at time r+c
    # Time when we arrive at (r,c) = r + c

    INF = float('inf')
    dp = [[INF] * M for _ in range(N)]
    dp[0][0] = 0

    for time_val in range(N + M - 1):  # from t=0 to t=N+M-2
        for r in range(N):
            c = time_val - r
            if c < 0 or c >= M:
                continue

            # Add energy cost from transformers at this time and position
            cost = 0
            for tx, ty, td, t_start, te in transformers:
                if t_start <= time_val:
                    # Transformer is active at time (time_val - t_start)
                    rev_time = time_val - t_start
                    # Position in cycle: rev_time % 4
                    pos_in_cycle = rev_time % 4

                    # positions: 0:(tx,ty), 1:(tx+td, ty-td), 2:(tx+td, ty), 3:(tx, ty+td)
                    if pos_in_cycle == 0:
                        pr, pc = tx, ty
                    elif pos_in_cycle == 1:
                        pr, pc = tx + td, ty - td
                    elif pos_in_cycle == 2:
                        pr, pc = tx + td, ty
                    else:  # pos_in_cycle == 3
                        pr, pc = tx, ty + td

                    if r == pr and c == pc:
                        cost += te
                        break  # Already counted if multiple transformers at same spot

            if dp[r][c] != INF:
                dp[r][c] += cost

            # Propagate to next cells
            if r < N - 1 and dp[r][c] + cost != INF:
                dp[r + 1][c] = min(dp[r + 1][c], dp[r][c] + cost)
            if c < M - 1 and dp[r][c] + cost != INF:
                dp[r][c + 1] = min(dp[r][c + 1], dp[r][c] + cost)

    result = dp[N-1][M-1]
    return str(result) + '\n'

