    n, m = map(int, input_str.strip().split())

    roots = set()

    for b in range(1, n + 1):
        if b * b <= m:
            start_k = 0
        else:
            start_k = int((b * b - m) ** 0.5) + 1

        # k must satisfy: 0 <= k < b and b^2 - k^2 <= m
        # So k^2 >= b^2 - m, which means k >= ceil(sqrt(max(0, b^2 - m)))

        max_k = min(b - 1, int((b * b - 1) ** 0.5) if b > 1 else 0)
        end_k = b - 1 if b * b - 1 <= m else int((b * b - m) ** 0.5)

        for k in range(start_k, end_k + 1):
            roots.add(-b + k)
            if k > 0:
                roots.add(-b - k)

    return str(len(roots))

